/**
 * The single source for the public features page and the agent-readable files
 * (`public/llms.txt` and `public/features.md`, generated by
 * `scripts/build-llms-txt.ts`). Only list what the code really does.
 */

import { DIANA_URL, REPO_URL, SITE_URL } from "./site";

export { REPO_URL, SITE_URL };

export type GroupId = "read" | "ask" | "protect" | "data" | "share" | "speed" | "build";

export type Feature = {
  group: GroupId;
  name: string;
  /** One plain sentence about what it does for the person using it. */
  summary: string;
  /** Where you find it. */
  where: string;
  /** How an agent or script reaches it, when it can. */
  surface?: string;
};

