/** The text of `public/llms.txt`: a short index for agents. */
export function renderLlmsTxt(): string {
  return `# Oncobase

> Oncobase is an open-source (MIT) knowledge base for taking control of your care. Publish a vault of markdown notes, papers, and results to a searchable reader with AI search and chat, role-based privacy, inline redaction, and clinical viewers.

It was inspired by Sid Sijbrandij's osteosarc.com (https://osteosarc.com/).

## Start here

- [Oncobase](${SITE_URL}/): what it is and who it is for.
- [Everything Oncobase can do](${SITE_URL}/features.md): every feature, where it lives, and how to call it, in markdown. The same content as the [features page](${SITE_URL}/features).
- [How Oncobase compares](${SITE_URL}/compare.md): when to use Notion, Obsidian, Yuga Bio, and others instead, and what to reuse if you are building your own. The same content as the [comparison page](${SITE_URL}/compare).
- [Source code and README](${REPO_URL}): MIT licensed.
- [Diana's knowledge base](${DIANA_URL}/): the first site built on Oncobase.

## Two ways to use it with an agent

- Have your agent build your own knowledge base with the \`oncobase\` CLI (\`oncobase check\`, then \`oncobase publish\`) and the bundled skills (\`oncobase skills\`).
- Or have your agent reference Oncobase while it builds yours: the code is MIT licensed, so any part can be read, copied, and adapted.

## Notes for agents

- The reader is a client-rendered web app; most content needs a signed-in session or the site password.
- The public guides at ${DIANA_URL}/education need no password, and neither do this site's pages (the home page, features, and compare).
`;
}

const bullet = (feature: Feature) =>
  `- **${feature.name}.** ${feature.summary} Where: ${feature.where}.${feature.surface ? ` Interface: \`${feature.surface}\`.` : ""}`;

/** The text of `public/features.md`: the features page as markdown, for people and agents. */
export function renderFeaturesMd(): string {
  const sectionGroup: Partial<Record<SectionId, GroupId>> = {
    read: "read", ask: "ask", protect: "protect", data: "data", collaborate: "share", speed: "speed", build: "build",
  };
  const order: SectionId[] = ["read", "ask", "protect", "data", "collaborate", "speed", "details", "build"];
  const sections = order
    .map((id) => {
      const copy = sectionCopy[id];
      const head = `## ${copy.heading}\n\n${copy.intro}`;
      if (id === "details") {
        const body = detailGroups
          .map((group) =>
            [`### ${group.title}`, "", ...detailItems.filter((item) => item.group === group.id).map((item) => `- **${item.title}.** ${item.text}`)].join("\n"),
          )
          .join("\n\n");
        return `${head}\n\n${body}`;
      }
      const group = sectionGroup[id]!;
      const list = groupFeatures(group).map(bullet).join("\n");
      if (id !== "build") return `${head}\n\n${list}`;
      const tables = interfaceCategories
        .map((category) =>
          [
            `### ${category.title}`,
            "",
            "| Name | Kind | What it does | Auth |",
            "| --- | --- | --- | --- |",
            ...interfaces
              .filter((item) => item.category === category.id)
              .map((item) => `| \`${item.name}\` | ${item.kind} | ${item.does} | ${item.auth} |`),
          ].join("\n"),
        )
        .join("\n\n");
      return `${head}\n\n${list}\n\n### Start\n\n\`\`\`\noncobase init --site my-site --vault ./vault --publish-url https://my-site.example\noncobase skills\noncobase check\noncobase publish --embeddings auto\n\`\`\`\n\n### Interfaces\n\nAuth: Gate = the site's shared-password cookie; Session = an account cookie; Publish token = \`Authorization: Bearer wpt_…\`; Public = none.\n\n${tables}`;
    })
    .join("\n\n");
  return `# Everything Oncobase can do

> ${heroLede}

Source: ${REPO_URL} (MIT). Live example: ${DIANA_URL}/. This page: ${SITE_URL}/features. How it compares with Notion, Obsidian, and others: ${SITE_URL}/compare.md. Inspired by Sid Sijbrandij's osteosarc.com (https://osteosarc.com/).

${sections}

## Not available today

Sorting or filtering inside tables, and an MCP server.
`;
}
